// NEU (Feature #4): Stufe direkt im Ablauf-Zeitstrahl anklicken, statt nur ueber
// das Dropdown oben. Nutzt dieselbe speichern()-Pipeline wie das Dropdown, also
// greifen alle bestehenden Tore/Dialoge (mgTorFehlt) unveraendert weiter.
W.kZielKlick=["Klicken, um zu dieser Stufe zu wechseln","Нажми, чтобы перейти на этот этап","Click to jump to this stage"];
// Beschriftung des Plattform-Links je Quelle: vorher stand auf NeedHelp-/KnowS-Karten
// faelschlich "Auf Renovero öffnen", obwohl der Link zu NeedHelp bzw. KnowS fuehrt.
function kLinkWort(a){
  var q=a.quelle||"";
  var p=q==="needhelp"?"NeedHelp":(q==="knows"?"KnowS":(q==="renovero"||!q?"Renovero":kQuelleText(q)));
  return LANG===1?"Открыть на "+p:(LANG===2?"Open on "+p:"Auf "+p+" öffnen");}
function kQuelleText(q){
  if(!q)return "";
  if(q==="renovero")return "Renovero";
  if(q==="knows")return "KnowS";
  if(q==="needhelp")return "NeedHelp";
  if(q==="gmail")return "E-Mail";
  if(q==="website")return t("qlWebsite");
  if(q==="manuell")return t("qlManuell");
  if(q==="webhook")return "Webhook";
  if(q==="excel_import")return "Excel";
  return q;}
var FELDER=[
 {t:"kundendaten",f:[
   {k:"kunde_vorname",l:["Vorname","Имя"]},{k:"kunde_nachname",l:["Nachname","Фамилия"]},
   {k:"kunde_telefon",l:["Telefon","Телефон"]},{k:"kunde_email",l:["E-Mail","E-Mail"]},
   {k:"kunde_strasse",l:["Strasse","Улица"]},{k:"plz",l:["PLZ","Индекс"]},{k:"ort",l:["Ort","Город"]},
   {k:"kunde_typ",l:["Kundentyp","Тип клиента"],opt:["privat","firma","verwaltung","architekt","generalunternehmer"]},
   {k:"kunde_firma",l:["Firma","Фирма"]}]},
 {t:"auftrag",f:[
   {k:"titel",l:["Titel","Название"]},
   {k:"prioritaet_stufe",l:["Priorität","Приоритет"],opt:["","Dringend","Wichtig","Normal","Niedrig"]},
   {k:"nehmen_wir",l:["Nehmen wir?","Берём?"],opt:["","Ja","Nein","Vielleicht"]},
   {k:"prioritaet_text",l:["Dringlichkeit","Срочность"]},
   {k:"naechste_aktion",l:["Nächste Aktion","Следующий шаг"]}]},
 {t:"termine",f:[
   {k:"termin_at",l:["Termin","Встреча"],typ:"datetime-local",zeigt:"terminAnzeige"},
   {k:"deadline_offerte",l:["Deadline Offerte","Дедлайн офферты"],typ:"date",zeigt:"deadlineAnzeige"},
   {k:"arbeitsbeginn_at",l:["Arbeitsbeginn","Начало работ"],typ:"datetime-local",zeigt:"startAnzeige"},
   {k:"arbeitsende_at",l:["Arbeitsende","Конец работ"],typ:"datetime-local",zeigt:"endeAnzeige"},
   {k:"arbeitsbeginn",l:["Beginn (Text)","Начало (текст)"]}]},
 {t:"abrechnung",f:[
   {k:"offerte_status",l:["Offerte","Офферта"]},{k:"offerte_absenden",l:["Offerte gesendet","Офферта отправлена"]},
   {k:"unterschrift",l:["Unterschrift Kunde","Подпись клиента"]},{k:"buchhaltung",l:["Buchhaltung","Бухгалтерия"]},
   {k:"offerte_link",l:["Offerte-Link","Ссылка на офферту"]},{k:"renovero_link",l:["Renovero-Link","Ссылка Renovero"]}]}];

function fl(f){return f.l[LANG]||f.l[0];}
function feldAnzeige(a,f){ if(f.zeigt)return a[f.zeigt]||""; return a[f.k]||""; }

function kvBlock(a,grp){
  var h="",leer=true;
  for(var i=0;i<grp.f.length;i++){var f=grp.f[i];
    if(EDIT===a.id){
      leer=false;
      h+="<dt>"+esc(fl(f))+"</dt><dd>";
      if(f.opt){h+="<select data-feld='"+f.k+"'>";
        for(var o=0;o<f.opt.length;o++){h+="<option value='"+esc(f.opt[o])+"'"+(String(a[f.k]||"")===f.opt[o]?" selected":"")+">"+(f.opt[o]||"—")+"</option>";}
        h+="</select>";}
      else h+="<input type='"+(f.typ||"text")+"' data-feld='"+f.k+"' value='"+esc(a[f.k]||"")+"'>";
      h+="</dd>";
    } else {
      var w=feldAnzeige(a,f);
      if(!w)continue;
      leer=false;
      // QA-Audit 2026-09-11 (#2 Kontakte/Adresse "alles in 1 Klick"): Telefon/E-Mail/Ort
      // standen bisher als reiner Text da - kein tel:/mailto:-Link, kein Kartenlink.
      var dd;
      if(f.k==="kunde_telefon"){
        var wa=kWaHref(w);
        dd="<a class='kKontakt' href='tel:"+esc(kTelHref(w))+"'>"+esc(w)+"</a>"
          +(wa?" <a class='kKontakt kKontaktWa' href='"+esc(wa)+"' target='_blank' rel='noopener'>WhatsApp</a>":"");
      } else if(f.k==="kunde_email"){
        dd="<a class='kKontakt' href='mailto:"+esc(w)+"'>"+esc(w)+"</a>";
      } else if(f.k==="ort"){
        var adr=[a.kunde_strasse,a.plz,a.ort].filter(Boolean).join(", ");
        dd=esc(w)+(adr?" <a class='kKontakt kKontaktKarte' href='https://www.google.com/maps/search/?api=1&query="
          +encodeURIComponent(adr)+"' target='_blank' rel='noopener'>"+t("kRouteOeffnen")+"</a>":"");
      } else {
        dd=esc(w);
      }
      h+="<dt>"+esc(fl(f))+"</dt><dd class='"+(f.k==="prioritaet_stufe"?prioCls(a.prio):"")+"'>"+dd+"</dd>";}}
  if(leer)return "";
  return "<div class='sec'><h3>"+t(grp.t)+"</h3><dl class='kv'>"+h+"</dl></div>";}

// Hilfsfunktionen fuer Telefon-Links - dieselbe CH-Normalisierung wie mgWaHref im Manager-Teil.
function kTelHref(tel){return String(tel||"").replace(/[^\d+]/g,"");}
function kWaHref(tel){
  var d=kTelHref(tel).replace(/[+]/g,"");
  if(!d)return "";
  if(d.charAt(0)==="0")d="41"+d.slice(1);
  return "https://wa.me/"+d;}

function langBlock(a,key,titel,hinweis,cls){
  var w=a[key]||"";
  if(EDIT===a.id){
    return "<div class='sec'><h3>"+titel+"</h3><textarea class='langfeld' data-feld='"+key+"'>"+esc(w)+"</textarea>"
      +(hinweis?"<div class='hinweis'>"+hinweis+"</div>":"")+"</div>";}
  if(!w)return "";
  return "<div class='sec'><h3>"+titel+"</h3><div class='"+cls+"'>"+esc(w)+"</div></div>";}

var STUFEN=[
 {k:"sNeu",  st:["NeuerLead"]},
 {k:"sKontakt", st:["Kontakt"]},
 {k:"sKalk", st:["OfferteErstellen"]},
 {k:"sPreis", st:["WartenAufAntwort"]},
 {k:"sAuftrag", st:["AuftragBestaetigt"]},
 {k:"sArbeit", st:["ArbeitInProzess"]},
 // QA-Fix 2026-09-11: 'wartet_auf_abnahme' (neuer Zwischenstatus aus crm_arbeit_uebergeben,
 // Monteur-Knopf "Arbeit beendet") fehlte hier komplett. stufeIndex() gab dafuer -1 zurueck,
 // wodurch vorKalk faelschlich TRUE wurde (idx<2) und ein Objekt, das gerade auf Abnahme
 // wartet, ploetzlich wieder die Knoepfe fuer "vor der Kalkulation" zeigte - und NIRGENDS
 // einen Knopf, um es abzuschliessen (der alte Knopf griff nur bei ArbeitInProzess).
 {k:"sAbnahme", st:["wartet_auf_abnahme"]},
 {k:"sFertig", st:["Abgeschlossen","Rechnung","Bezahlt"]}];

function stufeIndex(key){
  for(var i=0;i<STUFEN.length;i++){ if(STUFEN[i].st.indexOf(key)>=0) return i; }
  return -1;}

function ketteBlock(a){
  var idx=stufeIndex(a.key);
  var h="<div class='sec'><h3>"+t("ablauf")+"</h3><div class='kette'>";
  for(var i=0;i<STUFEN.length;i++){
    var cls=idx<0?"":(i<idx?"fertig":(i===idx?"jetzt":""));
    // NEU (#4): jede Stufe ausser der aktuellen ist bei Bearbeitungsrecht anklickbar -
    // fuehrt genau denselben speichern({pipeline_status:...}) wie das Dropdown aus,
    // also bleiben alle Tore (mgTorFehlt-Dialoge) unveraendert in Kraft.
    var klick=(USER.edit&&!a.lost&&i!==idx);
    if(klick)cls+=(cls?" ":"")+"klick";
    var wer="";
    if(STUFEN[i].k==="sKalk"&&a.ingenieur)wer=t("ingenieur")+": "+a.ingenieur;
    else if(STUFEN[i].k==="sPreis"&&a.betrag)wer="CHF "+chf(a.betrag)+(a.runde>1?" · "+t("runde")+" "+a.runde:"");
    else if(STUFEN[i].k==="sArbeit"&&a.teamNamen)wer=t("team")+": "+a.teamNamen;
    else if(STUFEN[i].k==="sNeu"&&a.manager)wer=t("manager")+": "+a.manager;
    h+="<div class='schritt "+cls+"'"+(klick?" data-key='"+esc(STUFEN[i].st[0])+"' title='"+esc(t("kZielKlick"))+"'":"")
     +"><span class='punkt'></span><div class='txt'><b>"+t(STUFEN[i].k)+"</b>"
     +(wer?"<span class='wer'>"+esc(wer)+"</span>":"")+"</div></div>";}
  h+="</div>";

  var marken="";
  if(a.key==="wartet_auf_abnahme")marken+="<span class='marke gelb'>"+t("kAbnahmeNoetig")+"</span> ";
  if(a.slaVerletzt)marken+="<span class='marke rot'>"+t("sla")+"</span> ";
  if(a.nachfassFaellig)marken+="<span class='marke gelb'>"+t("nachfassOffen")+"</span> ";
  if(a.besichtigung)marken+="<span class='marke'>"+t("besichtigungOffen")+"</span> ";
  if((a.tageStill||0)>=5)marken+="<span class='marke'>"+a.tageStill+" "+t("tageStill")+"</span> ";
  if(marken)h+="<div style='margin-top:12px'>"+marken+"</div>";

  if(USER.edit){
    var b="";
    var vorKalk=(a.key==="NeuerLead"||a.key==="Kontakt"||a.key===""||idx<2);
    if(!a.lost){
      if(vorKalk)b+="<button class='btn blau kA' data-a='an_ingenieur' data-id='"+esc(a.id)+"'>"+t("anIngenieur")+"</button>";
      if(a.key==="OfferteErstellen")b+="<button class='btn blau kA' data-a='preis_senden' data-id='"+esc(a.id)+"'>"+t("preisSenden")+"</button>";
      if(a.key==="WartenAufAntwort"){
        b+="<button class='btn gruen kA' data-a='auftrag' data-id='"+esc(a.id)+"'>"+t("auftragGewonnen")+"</button>";
        b+="<button class='btn alt kA' data-a='verhandelt' data-id='"+esc(a.id)+"'>"+t("verhandelt")+"</button>";
        b+="<button class='btn alt kA' data-a='nachfass' data-id='"+esc(a.id)+"'>"+t("nachfassen")+"</button>";}
      if(a.key==="AuftragBestaetigt"||a.key==="ArbeitInProzess")
        b+="<button class='btn blau kA' data-a='monteure' data-id='"+esc(a.id)+"'>"+t("monteure")+"</button>";
      if(a.key==="ArbeitInProzess")
        b+="<button class='btn gruen kA' data-a='abgeschlossen' data-id='"+esc(a.id)+"'>"+t("arbeitFertig")+"</button>";
      // QA-Fix 2026-09-11 (#3 Handover-Flow): der Monteur-Knopf "Arbeit beendet" schiebt
      // seit Schritt 1 nach 'wartet_auf_abnahme' - bis eben gab es dort aber KEINEN Knopf
      // fuer Buero/Juergen, um final abzuschliessen (nur ArbeitInProzess zeigte ihn).
      if(a.key==="wartet_auf_abnahme")
        b+="<button class='btn gruen kA' data-a='abgeschlossen' data-id='"+esc(a.id)+"'>"+t("kAbnahmeAbschliessen")+"</button>";
      if(vorKalk||a.key==="OfferteErstellen")
        b+="<button class='btn alt kA' data-a='besichtigung' data-id='"+esc(a.id)+"'>"+t("besichtigung")+"</button>";
    } else {
      b+="<button class='btn alt kA' data-a='reaktivieren' data-id='"+esc(a.id)+"'>"+t("reaktivieren")+"</button>";}
    if(b)h+="<div style='margin-top:14px'>"+b+"</div>";}

  var kv="";
  if(a.manager)kv+="<dt>"+t("manager")+"</dt><dd>"+esc(a.manager)+"</dd>";
  if(a.ingenieur)kv+="<dt>"+t("ingenieur")+"</dt><dd>"+esc(a.ingenieur)+"</dd>";
  if(a.teamNamen)kv+="<dt>"+t("team")+"</dt><dd>"+esc(a.teamNamen)+"</dd>";
  if(a.betrag)kv+="<dt>"+t("betrag")+"</dt><dd class='geld'>CHF "+chf(a.betrag)+"</dd>";
  if(a.stunden)kv+="<dt>"+t("stunden")+"</dt><dd class='geld'>"+a.stunden+"</dd>";
  if(a.basis)kv+="<dt>"+t("basis")+"</dt><dd>"+esc(a.basis)+"</dd>";
  if(a.interneNotiz)kv+="<dt>"+t("interne")+"</dt><dd>"+esc(a.interneNotiz)+"</dd>";
  if(kv)h+="<dl class='kv' style='margin-top:16px'>"+kv+"</dl>";
  return h+"</div>";}

// ===================== QA-Audit 2026-09-11: Karte "alles in 1 Klick" =====================
// Offerte-Status-Badge, Team+Stunden (geplant/erfasst) und eine kompakte Fotogalerie
// direkt in der Karte, statt dass man dafuer erst in einen anderen Reiter/Panel muesste.
// Fotos/Ist-Stunden kommen asynchron (dieselben Endpunkte wie Abnahme/Zeiterfassung),
// darum erst ein Platzhalter, dann kZusatzLaden() nachladen lassen.
var OFFERTE_STATUS_INFO={
  entwurf:    {cls:"offbadge grau",  wort:"offStEntwurf"},
  gesendet:   {cls:"offbadge blau",  wort:"offStGesendet"},
  angenommen: {cls:"offbadge gruen", wort:"offStAngenommen"},
  abgelehnt:  {cls:"offbadge rot",   wort:"offStAbgelehnt"}
};
function kOfferteBadge(a){
  var st=String(a.offerte_status||"").toLowerCase().trim();
  var info=OFFERTE_STATUS_INFO[st];
  if(!info&&!st&&!a.betrag)return "";
  var h="<div class='sec'><h3>"+t("kOfferteTitel")+"</h3>";
  if(info)h+="<span class='"+info.cls+"'>"+t(info.wort)+"</span>";
  else if(st)h+="<span class='offbadge grau'>"+esc(a.offerte_status)+"</span>";
  if(a.betrag)h+=" <span class='geld' style='margin-left:8px'>CHF "+chf(a.betrag)+"</span>";
  h+="</div>";
  return h;}

function kTeamBlock(a){
  var ids=a.monteurIds||[];
  if(!ids.length)return "";
  var namen=ids.map(function(id){
    var m=(typeof TEAM!=="undefined"&&TEAM)?TEAM.filter(function(x){return x.id===id;})[0]:null;
    return m?m.name:id;});
  return "<div class='sec' id='kTeamSec'><h3>"+t("kTeamTitel")+"</h3>"
   +"<div class='kTeamListe'>"+namen.map(function(n){return "<span class='kTeamChip'>"+esc(n)+"</span>";}).join("")+"</div>"
   +"<div class='klein' id='kStundenInfo'>"+esc(kPlanPraefix(a))+t("kIstStundenLaden")+"</div>"
   +"</div>";}

// Kein data-Attribut fuer den Praefix noetig - kZusatzLaden() hat dasselbe Objekt a
// bereits im Closure und kann ihn beim Nachladen einfach erneut berechnen.
function kPlanPraefix(a){
  return a.stunden?(t("kPlanStundenKurz")+": "+String(a.stunden)+" h · "):"";}

function kFotoBlock(a){
  // Sichtbarkeit/Rechte steuert der Server: foto_laden liefert ok:false bzw. eine leere
  // Liste, wenn diese Person hier keine Fotos sehen darf - kein Extra-Check noetig.
  return "<div class='sec' id='kFotoSec'><h3>"+t("kFotoTitel")+"</h3>"
   +"<div id='kFotoGitter' class='kfotogitter'><div class='klein'>"+t("laden")+"…</div></div></div>";}

function kZusatzBlock(a){
  return kOfferteBadge(a)+kTeamBlock(a)+kFotoBlock(a);}

var K_FOTO_PHASEN=[["vorher","foVorher"],["nachher","foNachher"],["mangel","foMangel"],["dokument","foDokument"]];

function kZusatzLaden(a){
  api({aktion:"zeit_laden",anfrage_id:a.id}).then(function(r){
    var el2=el("kStundenInfo");if(!el2||OFFEN!==a.id)return;
    var praefix=kPlanPraefix(a);
    if(!r||!r.ok){el2.textContent=praefix;return;}
    var summe=0;
    (r.eintraege||[]).forEach(function(z){summe+=Number(z.stunden)||0;});
    el2.textContent=praefix+t("kIstStunden")+": "+summe.toFixed(1)+" h";
  }).catch(function(){});

  api({aktion:"foto_laden",anfrage_id:a.id}).then(function(r){
    var host=el("kFotoGitter");if(!host||OFFEN!==a.id)return;
    if(!r||!r.ok){host.innerHTML="<div class='klein'>"+t("kFotoFehler")+"</div>";return;}
    var fotos=r.fotos||[];
    if(!fotos.length){host.innerHTML="<div class='klein'>"+t("kFotoKeine")+"</div>";return;}
    var h="",gezeigt={};
    K_FOTO_PHASEN.forEach(function(p){
      var teil=fotos.filter(function(f){return f.phase===p[0]&&f.mini;});
      if(!teil.length)return;
      teil.forEach(function(f){gezeigt[f.id]=true;});
      h+="<div class='kfotogruppe'><div class='klein kfotolabel'>"+t(p[1])+" · "+teil.length+"</div><div class='kfotorow'>"
