function api(p){
  return fetch(location.pathname,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify(p)})
    .then(function(r){return r.text().then(function(x){
      var j=null;try{j=JSON.parse(x);}catch(e){}
      if(!j)return {ok:false,error:"Server: "+r.status};
      return j;});})
    .catch(function(){return {ok:false,error:t("keineVerbindung")};});}

