    d.prioRang=z.prio_rang||3;
    d.statusRang=z.status_rang||50;
    d.titel=z.titel||"";
    d.beschreibung=z.beschreibung||"";
    d.kunden_nachricht=z.kunden_nachricht||"";
    d.plz=z.plz||z.kunde_plz||"";
