    d.kunde_strasse=z.adresse||z.kunde_strasse||"";
    d.kundeTyp=z.kunde_typ||d.kundeTyp||"privat";
    d.kunde_typ=z.kunde_typ||d.kunde_typ||"privat";
    d.kundeFirma=z.kunde_firma||"";
    d.kunde_firma=z.kunde_firma||"";
    d.projektNummer=z.projekt_nummer||d.projektNummer||"";
    d.istStunden=(z.ist_stunden===null||z.ist_stunden===undefined)?d.istStunden:Number(z.ist_stunden);
    d.rgOffen=(z.rg_offen===null||z.rg_offen===undefined)?d.rgOffen:Number(z.rg_offen);
    d.rgUeberfaellig=(z.rg_ueberfaellig===undefined)?d.rgUeberfaellig:!!z.rg_ueberfaellig;
    d.manager=z.manager_name||d.manager;
    d.managerId=z.manager_id||d.managerId;
    d.ingenieur=z.ingenieur_name||d.ingenieur;
    d.ingenieurId=z.ingenieur_id||d.ingenieurId;
