    d.teamNamen=z.team_namen||d.teamNamen;
    d.betrag=(z.offerte_betrag===null||z.offerte_betrag===undefined)?d.betrag:Number(z.offerte_betrag);
    d.slaVerletzt=!!z.sla_verletzt;
    d.nachfassFaellig=!!z.nachfass_faellig;
    d.besichtigung=!!z.braucht_besichtigung;
    d.tageStill=(z.tage_ohne_bewegung===null||z.tage_ohne_bewegung===undefined)?d.tageStill:Number(z.tage_ohne_bewegung);
    d.such=[d.nr,d.rnr,d.name,d.titel,d.ort,d.kommentar,d.manager,d.ingenieur,d.teamNamen].filter(Boolean).join(" ").toLowerCase();
    break;}}

function speichern(id,felder,elm,fertig){
  // Fix: wird die Pipeline-Stufe manuell VORWAERTS gesetzt (Dropdown, Stufen-Kette anklicken
  // oder Board-Drag&Drop - alle drei laufen ueber diese eine Funktion), ist ein alter
  // "Naechster Schritt"-Reminder (z.B. "Offerte einreichen bis ...") meist ueberholt und wuerde
  // sonst im Manager-Dashboard als ueberfaellig weiterhaengen, obwohl der Deal laengst weiter ist.
  // Wird automatisch mitgeloescht, ausser der Aufruf setzt naechste_aktion_am selbst explizit.
  if(felder&&felder.pipeline_status!==undefined&&felder.naechste_aktion_am===undefined){
    var altZeile=(typeof zeile==="function")?zeile(id):null;
    if(altZeile){
      var altIdx=stufeIndex(altZeile.key),neuIdx=stufeIndex(felder.pipeline_status);
      if(altIdx>=0&&neuIdx>altIdx&&(altZeile.naechste_aktion||altZeile.naechste_aktion_am)){
        felder.naechste_aktion="";felder.naechste_aktion_am="";}}}
  api({aktion:"speichern",id:id,felder:felder}).then(function(res){
    if(pruefeSession(res))return;
    if(!res.ok){if(elm)elm.classList.add("fehler");
      if(fertig)fertig(false,res.error);else alert(t("fehlerSpeichern")+(res.error||"?"));return;}
    if(res.zeile)uebernehmen(id,res.zeile);
    if(elm){elm.classList.remove("fehler");elm.classList.add("ok");
      setTimeout(function(){elm.classList.remove("ok");},1200);}
    if(fertig)fertig(true);});}

