  var ende="<div class='fehler' id='kFehler'></div><div style='margin-top:16px'>"
    +"<button class='btn blau' id='kGo'>"+t("senden")+"</button>"
    +"<button class='btn alt' onclick='modalZu()'>"+t("abbrechen")+"</button></div>";

  if(aktion==="an_ingenieur"){
    var ing=TEAM.filter(function(m){return m.ingenieur;});
    if(!ing.length)ing=TEAM.filter(function(m){return !m.monteur;});
    var o="";for(var i=0;i<ing.length;i++)o+="<option value='"+esc(ing[i].id)+"'"+(a.ingenieurId===ing[i].id?" selected":"")+">"+esc(ing[i].name)+"</option>";
