    el("kGo").onclick=function(){kAktionSenden({aktion:"an_ingenieur",id:id,ingenieur_id:el("kIng").value},this);};

  }else if(aktion==="preis_senden"){
    modalAuf(kopf
      +"<label>"+t("betrag")+" (CHF)</label><input id='kBetrag' class='mono' inputmode='decimal' value='"+(a.betrag||"")+"'>"
      +"<label>"+t("basis")+"</label><select id='kBasis'>"
        +"<option value='festpreis'"+(a.basis==="festpreis"?" selected":"")+">"+t("festpreis")+"</option>"
        +"<option value='regie'"+(a.basis==="regie"?" selected":"")+">"+t("regie")+"</option>"
        +"<option value='gemischt'"+(a.basis==="gemischt"?" selected":"")+">"+t("gemischt")+"</option></select>"
      +"<label>"+t("stunden")+"</label><input id='kStunden' class='mono' inputmode='decimal' value='"+(a.stunden||"")+"'>"
      +"<label>"+t("interne")+"</label><textarea id='kNotiz'></textarea>"+ende);
    el("kGo").onclick=function(){
      if(!el("kBetrag").value){el("kFehler").textContent=t("pflichtBetrag");return;}
      kAktionSenden({aktion:"preis_senden",id:id,betrag:el("kBetrag").value,basis:el("kBasis").value,
                     stunden:el("kStunden").value,notiz:el("kNotiz").value},this);};

  }else if(aktion==="monteure"){
    var mon=TEAM.filter(function(m){return m.monteur;});
    if(!mon.length){modalAuf(kopf+"<div class='hinweis'>"+t("keinTeam")+"</div>"
      +"<div style='margin-top:16px'><button class='btn alt' onclick='modalZu()'>"+t("abbrechen")+"</button></div>");return;}
    var vonDefault=a.arbeitsbeginn_at||new Date().toISOString().slice(0,16);
    var bisDefault=(function(){var d=new Date(vonDefault);d.setHours(d.getHours()+8);return d.toISOString().slice(0,16);})();
    var rows="";
    for(var m2=0;m2<mon.length;m2++){
      var drin=a.monteurIds.indexOf(mon[m2].id)>=0;
      rows+="<label class='kMonZeile' data-name='"+esc(mon[m2].name.toLowerCase())+"'>"
        +"<input type='checkbox' class='kMon' value='"+esc(mon[m2].id)+"'"+(drin?" checked":"")+"> "
        +"<span class='kMonName'>"+esc(mon[m2].name)+"</span>"
        +"<span class='kMonStatus' data-id='"+esc(mon[m2].id)+"'>…</span></label>";}
    modalAuf(kopf
      +"<label>"+t("kSuche")+"</label><input id='kSuch' placeholder='"+t("kSucheHin")+"' autocomplete='off'>"
      +"<label>"+t("start")+"</label><input type='datetime-local' id='kStart' value='"+esc(vonDefault)+"'>"
      +"<label>"+t("kEnde")+"</label><input type='datetime-local' id='kEnde' value='"+esc(bisDefault)+"'>"
      +"<label>"+t("kPlanStunden")+"</label><input id='kPlanStd' class='mono' inputmode='decimal' placeholder='8'>"
      +"<label>"+t("monteure")+"</label><div class='wahlliste' id='kMonListe'>"+rows+"</div>"+ende);

