      if(!von||!bis)return;
      api({aktion:"monteur_verfuegbarkeit",von:von,bis:bis}).then(function(r){
        if(pruefeSession(r))return;
        if(!r||!r.ok)return;
        (r.monteure||[]).forEach(function(mv){
          var s=document.querySelector(".kMonStatus[data-id='"+mv.id+"']");
          if(!s)return;
          var eigenes=a.monteurIds.indexOf(mv.id)>=0;
          if(mv.frei||eigenes){s.textContent=t("kMonFrei");s.className="kMonStatus kFrei";}
          else{
            var vz=mv.konflikt_von?new Date(mv.konflikt_von).toLocaleTimeString('de-CH',{hour:'2-digit',minute:'2-digit'}):"";
            var bz=mv.konflikt_bis?new Date(mv.konflikt_bis).toLocaleTimeString('de-CH',{hour:'2-digit',minute:'2-digit'}):"";
