  }else if(aktion==="verhandelt"){
    modalAuf(kopf+"<label>"+t("kWunschpreis")+"</label>"
      +"<input id='kBetrag' class='mono' inputmode='decimal' value='"+(a.budget||"")+"'>"
      +"<label>"+t("interne")+"</label><textarea id='kNotiz'></textarea>"+ende);
    el("kGo").onclick=function(){kAktionSenden({aktion:"verhandelt",id:id,betrag:el("kBetrag").value,notiz:el("kNotiz").value},this);};

  }else if(aktion==="nachfass"||aktion==="besichtigung"||aktion==="reaktivieren"){
