    el("kGo").onclick=function(){kAktionSenden({aktion:aktion,id:id,notiz:el("kNotiz").value},this);};

  }else if(aktion==="abgeschlossen"){
    modalAuf(kopf+"<div style='font-size:14.5px'>"+t("kArbeitAbschliessen")+"</div>"+ende);
