function abnMalen(behalten){
  var box=el("abnhuelleInhalt");if(!box)return;
  // #Fix (Scroll-Reset-Schutz): "Speichern" im Protokoll-Reiter zeichnet die Liste
  // per innerHTML komplett neu - bei 20+ Maengeln auf der Baustelle riss das den
  // Monteur nach jedem Speichern zurueck an den Listenanfang, er musste sich jedes
  // Mal neu zur zuletzt bearbeiteten Zeile durchscrollen. behalten=true (von
  // Speichern/Status-Aktionen im selben Reiter) haelt die Scrollposition; beim
  // Reiterwechsel (behalten nicht gesetzt) faengt der neue Reiter bewusst oben an.
  var vorScroll=behalten?box.scrollTop:0;
  var h="<div class='offreiter'>";
