  h+= ABN.reiter==="protokoll"?abnProtokollMaske():
      ABN.reiter==="bewertung"?abnBewertungMaske():abnFotoMaske();
  box.innerHTML=h;
  if(vorScroll)box.scrollTop=vorScroll;
  var rs=box.querySelectorAll(".offreit[data-ab]");
  for(var q=0;q<rs.length;q++)rs[q].onclick=function(){
    ABN.reiter=this.getAttribute("data-ab");abnMalen();};
  if(ABN.reiter==="protokoll")abnProtokollBinden();
  else if(ABN.reiter==="bewertung")abnBewertungBinden();
  else abnFotoBinden();}

