  if(!ABN.fotos.length)return h+"<div class='offLaden'>"+t("foKeine")+"</div>";
  var gezeigt={};
  for(var g=0;g<FO_PHASEN.length;g++){
    var teil=ABN.fotos.filter(function(f){return f.phase===FO_PHASEN[g][0];});
    if(!teil.length)continue;
    teil.forEach(function(f){gezeigt[f.id]=true;});
    h+="<div class='fogruppe'><div class='kztitel'>"+esc(t(FO_PHASEN[g][1]))+" · "+teil.length+"</div>"
      +"<div class='fogitter'>";
    for(var i=0;i<teil.length;i++)h+=foKarteHtml(teil[i]);
    h+="</div></div>";}
  // Fotos mit einem phase-Wert, den FO_PHASEN nicht kennt (alte Daten, Tippfehler,
  // ein serverseitig neuer Wert), zaehlten im Tab-Badge oben mit - tauchten hier
  // aber in KEINER Gruppe auf und waren fuer den Nutzer faktisch verschwunden.
  var rest=ABN.fotos.filter(function(f){return !gezeigt[f.id];});
  if(rest.length){
    h+="<div class='fogruppe'><div class='kztitel'>"+esc(t("foSonstige"))+" · "+rest.length+"</div>"
      +"<div class='fogitter'>";
    for(var i=0;i<rest.length;i++)h+=foKarteHtml(rest[i]);
    h+="</div></div>";}
  return h;}

function abnFotoBinden(){
  var box=el("abnhuelleInhalt");if(!box)return;
