  if(k)k.onchange=function(){foHochladen(this.files);this.value="";};
  if(d)d.onchange=function(){foHochladen(this.files);this.value="";};
  var karten=box.querySelectorAll(".fokarte img");
  for(var i=0;i<karten.length;i++)karten[i].onclick=function(){
    foGross(this.parentNode.getAttribute("data-f"));};
