    e.stopPropagation();foWeg(this.getAttribute("data-w"));};}

// Bild im Browser verkleinern, damit auch ein Handyfoto durch die Leitung passt
function foKlein(datei,kante,qual,dann){
  var fr=new FileReader();
  fr.onerror=function(){dann(null);};
  fr.onload=function(){
    var img=new Image();
    img.onerror=function(){dann(null);};
    img.onload=function(){
      var s=Math.min(1,kante/Math.max(img.width,img.height));
      var c=document.createElement("canvas");
      c.width=Math.max(1,Math.round(img.width*s));
      c.height=Math.max(1,Math.round(img.height*s));
      var x=c.getContext("2d");
      x.fillStyle="#ffffff";x.fillRect(0,0,c.width,c.height);
      x.drawImage(img,0,0,c.width,c.height);
      try{dann(c.toDataURL("image/jpeg",qual));}catch(e){dann(null);}};
    img.src=fr.result;};
  fr.readAsDataURL(datei);}

function foHochladen(dateien){
  if(!dateien||!dateien.length)return;
  var phase=el("foPhase")?el("foPhase").value:"vorher";
  var liste=[],i;
  for(i=0;i<dateien.length;i++)if(/^image\\//.test(dateien[i].type))liste.push(dateien[i]);
  if(!liste.length)return;
  ABN.hochVon=liste.length;ABN.hoch=0;
  var naechstes=function(n){
    if(n>=liste.length){foStand("");abnAllesLaden(function(){abnMalen();});return;}
    ABN.hoch=n+1;foStand(t("foLaedt").replace("%1",n+1).replace("%2",liste.length));
    foEines(liste[n],phase,function(fehler){
      if(fehler){foStand(fehler);setTimeout(function(){foStand("");},4000);
        abnAllesLaden(function(){abnMalen();});return;}
      naechstes(n+1);});};
  naechstes(0);}

function foStand(txt){var s=el("foStand");if(s)s.textContent=txt||"";}

function foEines(datei,phase,fertig){
  foKlein(datei,1600,0.72,function(gross){
    if(!gross){fertig("Bild konnte nicht gelesen werden");return;}
    var senden=function(bild){
      foKlein(datei,300,0.62,function(mini){
        api({aktion:"foto_speichern",anfrage_id:ABN.anfrage,phase:phase,
             titel:(datei.name||"").slice(0,120),daten:bild,mini:mini||""}).then(function(r){
          if(pruefeSession(r))return;
          fertig((r&&r.ok)?null:((r&&r.error)||"Fehler"));});});};
    if(gross.length>1300000)foKlein(datei,1100,0.58,function(kl){senden(kl||gross);});
    else senden(gross);});}

function foGross(id){
  api({aktion:"foto_voll",id:id}).then(function(r){
    if(pruefeSession(r))return;
    if(!r||!r.ok||!r.daten)return;
    var alt=el("fovoll");if(alt)alt.remove();
    var d=document.createElement("div");
    d.id="fovoll";d.className="fovoll";
    d.innerHTML="<img src='"+esc(r.daten)+"' alt=''>"
      +(r.titel?"<span class='fovolltxt'>"+esc(r.titel)+"</span>":"")
      +"<button class='fovollzu' aria-label='Schliessen'>&times;</button>";
    document.body.appendChild(d);
    var zu=function(){d.remove();};
    d.onclick=zu;d.querySelector(".fovollzu").onclick=zu;});}

function foWeg(id){
  if(!confirm(t("foWirklich")))return;
  api({aktion:"foto_loeschen",id:id}).then(function(r){
    if(pruefeSession(r))return;
    if(!r||!r.ok){alert((r&&r.error)||"Fehler");return;}
    abnAllesLaden(function(){abnMalen();});});}

