function abnSigBinden(cid){
  var c=el(cid);if(!c)return;
  var b=c.getBoundingClientRect();
  var r=window.devicePixelRatio||1;
  var br=Math.max(60,Math.round(b.width)),ho=Math.max(60,Math.round(b.height));
  c.width=Math.round(br*r);c.height=Math.round(ho*r);
  var x=c.getContext("2d");
  x.setTransform(r,0,0,r,0,0);
  x.lineWidth=2.1;x.lineCap="round";x.lineJoin="round";x.strokeStyle="#141A20";
  var vor=c.getAttribute("data-wert");
  if(vor){var im=new Image();im.onload=function(){
    var s=Math.min(br/im.width,ho/im.height,1);
    x.drawImage(im,0,0,im.width*s,im.height*s);};im.src=vor;}
  if(c.hasAttribute("data-fix"))return;
  var zieht=false,lx=0,ly=0,pkte=[];
  var punkt=function(e){var q=c.getBoundingClientRect();
    var p=(e.touches&&e.touches[0])||e;
    return {x:p.clientX-q.left,y:p.clientY-q.top};};
  var ab=function(e){e.preventDefault();zieht=true;var p=punkt(e);lx=p.x;ly=p.y;pkte=[p];
    c.setAttribute("data-hat","1");
    var hint=c.parentNode.querySelector(".pksighint");if(hint)hint.style.display="none";};
  // #Fix (Glaettung): rohe lineTo-Segmente zwischen einzelnen mousemove/touchmove-
  // Punkten wirkten auf jedem Geraet mit niedriger Abtastrate (v.a. Touch) eckig
  // und kantig - eine Unterschrift soll wie eine Unterschrift aussehen, nicht wie
  // ein Polygonzug. Standard-Technik: quadratische Kurve durch die Mittelpunkte
  // je zweier aufeinanderfolgender Segmente, der eigentliche Messpunkt als
  // Kontrollpunkt - das rundet jede Ecke automatisch ab, ohne Verzoegerung.
  var zu=function(e){if(!zieht)return;e.preventDefault();var p=punkt(e);
    pkte.push(p);
    var n=pkte.length;
    if(n<3){x.beginPath();x.moveTo(lx,ly);x.lineTo(p.x,p.y);x.stroke();}
    else{
      var m1={x:(pkte[n-3].x+pkte[n-2].x)/2,y:(pkte[n-3].y+pkte[n-2].y)/2};
      var m2={x:(pkte[n-2].x+pkte[n-1].x)/2,y:(pkte[n-2].y+pkte[n-1].y)/2};
      x.beginPath();x.moveTo(m1.x,m1.y);x.quadraticCurveTo(pkte[n-2].x,pkte[n-2].y,m2.x,m2.y);x.stroke();}
    lx=p.x;ly=p.y;};
  var auf=function(){zieht=false;pkte=[];};
  c.addEventListener("mousedown",ab);c.addEventListener("mousemove",zu);
  window.addEventListener("mouseup",auf);
  c.addEventListener("touchstart",ab,{passive:false});
  c.addEventListener("touchmove",zu,{passive:false});
  c.addEventListener("touchend",auf);c.addEventListener("touchcancel",auf);}

function abnSigWert(cid){
  var c=el(cid);if(!c)return undefined;
  if(c.getAttribute("data-hat")==="1"){try{return c.toDataURL("image/png");}catch(e){return undefined;}}
  if(c.getAttribute("data-hat")==="0")return "";
  return undefined;}

function abnProtokollBinden(){
  var box=el("abnhuelleInhalt");if(!box)return;
  abnSigBinden("pkSigKunde");abnSigBinden("pkSigFirma");

  var wahl=box.querySelectorAll(".pkwahl button");
  for(var i=0;i<wahl.length;i++)wahl[i].onclick=function(){
    var z=this.parentNode;
    var an=this.classList.contains("an");
    z.querySelector(".pkja").classList.remove("an");
    z.querySelector(".pknein").classList.remove("an");
    if(!an)this.classList.add("an");};

  var add=el("pkAdd");
  if(add)add.onclick=function(){
    var w=el("pkMaengel"),leer=w.querySelector(".pkleer");
    if(leer)leer.remove();
    w.insertAdjacentHTML("beforeend",abnMangelZeile({text:"",frist:"",behoben:false},false));
    abnMangelBinden();
    var neu=w.querySelectorAll(".mgText");if(neu.length)neu[neu.length-1].focus();};
  abnMangelBinden();

  var weg=box.querySelectorAll(".pksigweg");
  for(var q=0;q<weg.length;q++)weg[q].onclick=function(){
    var c=el(this.getAttribute("data-c"));if(!c)return;
    var x=c.getContext("2d");x.clearRect(0,0,c.width,c.height);
    c.setAttribute("data-hat","0");c.removeAttribute("data-wert");
    var hint=c.parentNode.querySelector(".pksighint");if(hint)hint.style.display="";};

  var s=el("pkSave");if(s)s.onclick=function(){abnSpeichern(function(){abnMalen(true);});};
  // Abnehmen/Vorbehalt/Verweigern sperren das Protokoll sofort (nur ein Admin kann
  // es wieder oeffnen) - vorher gab es dafuer keine Rueckfrage, ein Fehlklick war
  // also nicht rueckgaengig zu machen ohne einen Administrator zu bemuehen.
  var ab=el("pkAb");if(ab)ab.onclick=function(){
    if(confirm(t("pkSicherStatus").replace("%1",abnStatusWort("abgenommen"))))abnSetzen("abgenommen");};
  var vo=el("pkVor");if(vo)vo.onclick=function(){
    if(confirm(t("pkSicherStatus").replace("%1",abnStatusWort("vorbehalt"))))abnSetzen("vorbehalt");};
  var ve=el("pkVerw");if(ve)ve.onclick=function(){
    if(confirm(t("pkSicherStatus").replace("%1",abnStatusWort("verweigert"))))abnSetzen("verweigert");};
  var au=el("pkAuf");if(au)au.onclick=function(){
    api({aktion:"protokoll_status",anfrage_id:ABN.anfrage,status:"entwurf"}).then(function(r){
      if(pruefeSession(r))return;
      if(!r||!r.ok){alert((r&&r.error)||"Fehler");return;}
      ABN.protokoll=r.protokoll;abnMalen();});};
  // Solange das Protokoll noch bearbeitbar ist, erst speichern und DANN drucken -
  // sonst druckt man den zuletzt GESPEICHERTEN Stand, nicht die Aenderungen, die
  // gerade noch unsichtbar im Formular stehen (z.B. frisch angehakte Punkte).
  var pr=el("pkPrint");if(pr)pr.onclick=abnSchreiben()?function(){abnSpeichern(abnDrucken);}:abnDrucken;}

function abnMangelBinden(){
  var box=el("pkMaengel");if(!box)return;
  var weg=box.querySelectorAll(".mgWeg");
  for(var i=0;i<weg.length;i++)weg[i].onclick=function(){
    var z=this.parentNode;z.parentNode.removeChild(z);
    if(!box.querySelectorAll(".pkmangel").length)
      box.innerHTML="<div class='pkleer'>"+t("pkKeineMaengel")+"</div>";};}

function abnSammeln(){
  var box=el("abnhuelleInhalt");
  var punkte=[],vor=abnPunkte();
  var zeilen=box.querySelectorAll(".pkzeile");
  for(var i=0;i<zeilen.length;i++){
    var z=zeilen[i],ok=null;
    if(z.querySelector(".pkja").classList.contains("an"))ok=true;
    else if(z.querySelector(".pknein").classList.contains("an"))ok=false;
    punkte.push({k:(vor[i]&&vor[i].k)||z.querySelector(".pktext").textContent,
                 ok:ok,n:z.querySelector(".pknotiz").value});}
  var maengel=[],mz=box.querySelectorAll(".pkmangel");
  for(var m=0;m<mz.length;m++){
    var txt=mz[m].querySelector(".mgText").value.trim();
    if(!txt)continue;
    maengel.push({text:txt,frist:mz[m].querySelector(".mgDatum").value||null,
                  behoben:mz[m].querySelector(".mgBehoben").checked});}
  var f={datum:el("pkDatum")?el("pkDatum").value:null,
         ort:el("pkOrt")?el("pkOrt").value:"",
         punkte:punkte,maengel:maengel,
         bemerkung:el("pkBem")?el("pkBem").value:"",
         kunde_name:el("pkKundeName")?el("pkKundeName").value:"",
         firma_name:el("pkFirmaName")?el("pkFirmaName").value:""};
  var ku=abnSigWert("pkSigKunde");if(ku!==undefined)f.kunde_unterschrift=ku;
  var fi=abnSigWert("pkSigFirma");if(fi!==undefined)f.firma_unterschrift=fi;
  return f;}

function abnSpeichern(dann){
  if(ABN.laeuft)return;ABN.laeuft=true;
  var knopf=el("pkSave");if(knopf){knopf.disabled=true;knopf.textContent=t("abnLaeuft");}
  api({aktion:"protokoll_speichern",anfrage_id:ABN.anfrage,felder:abnSammeln()}).then(function(r){
    ABN.laeuft=false;
    if(pruefeSession(r))return;
    if(!r||!r.ok){alert((r&&r.error)||"Fehler");
      if(knopf){knopf.disabled=false;knopf.textContent=t("speichern");}return;}
    ABN.protokoll=r.protokoll;
    if(dann)dann();});}

function abnSetzen(neu){
  abnSpeichern(function(){
    api({aktion:"protokoll_status",anfrage_id:ABN.anfrage,status:neu}).then(function(r){
      if(pruefeSession(r))return;
      if(!r||!r.ok){alert((r&&r.error)||"Fehler");abnMalen();return;}
      ABN.protokoll=r.protokoll;
      if(neu==="abgenommen"||neu==="vorbehalt"){
        api({aktion:"bewertung_laden",anfrage_id:ABN.anfrage}).then(function(b){
          if(b&&b.ok){ABN.bew=b.bewertung||null;ABN.abgenommen=!!b.abgenommen;
            ABN.vorschlag=b.vorschlag||ABN.vorschlag;}
          ABN.reiter=ABN.bewDarf?"bewertung":"protokoll";abnMalen();});
      } else abnMalen();});});}

