function abnBewertungBinden(){
  var box=el("abnhuelleInhalt");if(!box)return;
  var kn=el("bwKanal");
  if(kn)kn.onchange=function(){
    var li=el("bwLink");
    if(li&&!(ABN.bew&&ABN.bew.link))
      li.value=this.value==="renovero"?(ABN.links.renovero||""):(ABN.links.google||"");};
  var st=box.querySelectorAll(".bwstern");
  for(var i=0;i<st.length;i++)st[i].onclick=function(){
    var n=parseInt(this.getAttribute("data-s"),10)||0;
    var alle=box.querySelectorAll(".bwstern");
    for(var q=0;q<alle.length;q++){
      var v=parseInt(alle[q].getAttribute("data-s"),10)||0;
      if(v>0)alle[q].classList.toggle("an",v<=n);}
    box.setAttribute("data-sterne",n);};
  var sp=el("bwSave");if(sp)sp.onclick=function(){bwSpeichern(function(){bwMeldung(t("abnGespeichert"));});};
  var ko=el("bwKopie");if(ko)ko.onclick=function(){
    var ta=el("bwText");if(!ta)return;
    ta.select();ta.setSelectionRange(0,99999);
    var gut=false;try{gut=document.execCommand("copy");}catch(e){}
    if(!gut&&navigator.clipboard)navigator.clipboard.writeText(ta.value);
    bwMeldung(t("bwKopiert"));};
  var ma=el("bwMail");if(ma)ma.onclick=function(){
    var ta=el("bwText");
    var betreff=(ABN.firma.firma||"")+" \\u2013 "+(ABN.objekt.nr||"");
    location.href="mailto:"+encodeURIComponent(ABN.kunde.email||"")
      +"?subject="+encodeURIComponent(betreff)
      +"&body="+encodeURIComponent(ta?ta.value:"");};
  var gf=el("bwGefragt");if(gf)gf.onclick=function(){
    bwSpeichern(function(){
      api({aktion:"bewertung_angefragt",anfrage_id:ABN.anfrage,
           kanal:el("bwKanal")?el("bwKanal").value:"google"}).then(function(r){
        if(pruefeSession(r))return;
        if(!r||!r.ok){alert((r&&r.error)||"Fehler");return;}
        ABN.bew=r.bewertung;abnMalen();});});};}

function bwMeldung(txt){
  var m=el("bwMeldung");if(!m)return;
  m.textContent=txt||"";
  setTimeout(function(){if(el("bwMeldung"))el("bwMeldung").textContent="";},2600);}

function bwSpeichern(dann){
  var box=el("abnhuelleInhalt");
  var sterne=box.getAttribute("data-sterne");
  var f={kanal:el("bwKanal")?el("bwKanal").value:"google",
         status:el("bwStatus")?el("bwStatus").value:"offen",
         link:el("bwLink")?el("bwLink").value:"",
         text:el("bwText")?el("bwText").value:"",
         notiz:el("bwNotiz")?el("bwNotiz").value:""};
  if(sterne!==null&&sterne!==undefined)f.sterne=(parseInt(sterne,10)||0)?parseInt(sterne,10):null;
  api({aktion:"bewertung_speichern",anfrage_id:ABN.anfrage,felder:f}).then(function(r){
    if(pruefeSession(r))return;
    if(!r||!r.ok){alert((r&&r.error)||"Fehler");return;}
    ABN.bew=r.bewertung;if(dann)dann();});}

