// ===================== PFLICHT-PASSWORT: NICHT MEHR WEGDRUECKBAR =====================
// Der erzwungene Passwortdialog liess sich mit Esc oder Klick daneben schliessen.
// Ergebnis: Flag blieb stehen, die Abfrage kam bei jedem Login wieder.
(function(){
  if(typeof passwortAuf!=="function"||typeof modalZu!=="function")return;
  var altZu=modalZu, altAuf=passwortAuf, PFLICHT=false;
  modalZu=function(){ if(PFLICHT)return; altZu(); };
  passwortAuf=function(pflicht){
    altAuf(pflicht);
    if(!pflicht)return;
    PFLICHT=true;
    var s=el("pSave");
    if(!s)return;
    s.onclick=function(){
      var f=el("pFehler");
      if(el("pNeu").value!==el("pNeu2").value){
        f.textContent=t("pwMismatch");return;}
      s.disabled=true;
      api({aktion:"passwort",alt:el("pAlt").value,neu:el("pNeu").value}).then(function(res){
        s.disabled=false;
        if(pruefeSession(res))return;
        if(!res||!res.ok){f.textContent=(res&&res.error)||"Fehler";return;}
        PFLICHT=false;USER.pwChange=false;
        modalZu();
        alert(t("pwGeaendert"));});};};
  // Der Dialog aus Teil 2 ist beim Laden schon offen — einmal gehaertet neu oeffnen
  if(USER.pwChange&&el("modal")){ altZu(); passwortAuf(true); }
})();

// ===================== RENOVERO-MEDIEN + FRIST IN DER KARTE =====================
function medFristText(iso,ueber){
  if(!iso)return null;
  var d=new Date(iso+"T12:00:00");if(isNaN(d.getTime()))return null;
  var heute=new Date();heute.setHours(12,0,0,0);
  var tage=Math.round((d-heute)/86400000);
  var txt;
  if(ueber||tage<0)txt=t("dlWeg");
  else if(tage===0)txt=t("dlHeute");
  else if(tage===1)txt=t("dlMorgen");
  else txt=t("dlTage").replace("%1",tage);
  var cls=(ueber||tage<0)?"rot":(tage<=2?"gelb":"gruen");
  return {txt:t("dlFrist")+" "+esc(offDatumHum(iso))+" \u00b7 "+txt, cls:cls};
}

function medGross(url,video){
  var alt=el("fovoll");if(alt)alt.remove();
  var d=document.createElement("div");d.id="fovoll";d.className="fovoll";
  d.innerHTML=(video?"<video src='"+esc(url)+"' controls autoplay style='max-width:100%;max-height:92vh'></video>"
                    :"<img src='"+esc(url)+"' alt=''>")
    +"<button class='fovollzu' aria-label='Schliessen'>&times;</button>";
  document.body.appendChild(d);
  var zu=function(){d.remove();};
  d.onclick=function(e){if(e.target===d)zu();};
  d.querySelector(".fovollzu").onclick=zu;
}

function medKarte(a,karte){
  if(!a||!karte)return;
  var cb=karte.querySelector(".cb");if(!cb)return;

  // Frist-Banner ganz oben
  if(!karte.querySelector(".dlbanner")){
    var fr=medFristText(a.deadline_offerte,a.deadlineUeber);
    if(fr)cb.insertAdjacentHTML("afterbegin",
      "<div class='sec'><div class='dlbanner "+fr.cls+"'>"+fr.txt+"</div></div>");
  }

  // Galerie
  if(karte.querySelector(".medgal"))return;
  var med=a.medien||[];if(!med.length)return;
  var h="<div class='sec'><h3>"+t("medMaterial")+" <span class='mono' style='color:var(--muted)'>"+med.length+"</span></h3><div class='medgal'>";
  for(var i=0;i<med.length;i++){var m=med[i];
    if(m.bild){
      h+="<button class='medbild' data-voll='"+esc(m.voll)+"' title='"+esc(m.titel||"")+"'>"
        +"<img src='"+esc(m.mini||m.voll)+"' alt='' loading='lazy'></button>";
    } else {
      h+="<a class='medvideo' href='"+esc(m.voll)+"' target='_blank' rel='noopener'>&#9658; "
        +esc(m.titel||t("medVideo"))+"</a>";}}
  h+="</div></div>";
  // vor die Beschreibung einfuegen, sonst ans Ende
  var descSec=cb.querySelector(".desc");
  if(descSec&&descSec.closest(".sec"))descSec.closest(".sec").insertAdjacentHTML("beforebegin",h);
  else cb.insertAdjacentHTML("beforeend",h);
  var bs=cb.querySelectorAll(".medbild");
  for(var q=0;q<bs.length;q++)bs[q].onclick=function(){medGross(this.getAttribute("data-voll"),false);};
}

// ===================== STATUSMENUE: EIGENES DROPDOWN IM APP-STIL =====================
// Das native Auswahlfenster des Browsers ist immer hell und passt nicht zum Interface.
// Fuer die Status-Auswahl (.st) zeichnen wir ein eigenes Menue; alle uebrigen nativen
// Steuerelemente folgen ueber color-scheme wenigstens dem Hell/Dunkel-Thema.
function stZu(){
  var m=el("stmenue");if(!m)return;
  m.remove();
