function stAussen(e){var m=el("stmenue");if(m&&!m.contains(e.target))stZu();}
function stEsc(e){if(e.key==="Escape")stZu();}
function stRollt(e){var m=el("stmenue");if(m&&!m.contains(e.target))stZu();}

function stMenueAuf(sel){
  var offen=el("stmenue");
  if(offen&&offen.__sel===sel){stZu();return;}
  stZu();
  var r=sel.getBoundingClientRect();
  var d=document.createElement("div");
  d.id="stmenue";d.className="stmenue";d.setAttribute("role","listbox");
  d.__sel=sel;
  var h="";
  for(var i=0;i<sel.options.length;i++){var o=sel.options[i];
    var farbe=(typeof farbeVon==="function")?farbeVon(o.value):"#6B7280";
    h+="<div class='stwahl"+(o.selected?" an":"")+"' role='option' data-v='"+esc(o.value)+"'>"
      +"<span class='stpunkt' style='background:"+esc(farbe)+"'></span>"
      +"<span class='sttext'>"+esc(o.text)+"</span>"
      +(o.selected?"<span class='sthaken'>&#10003;</span>":"")
      +"</div>";}
  d.innerHTML=h;
  document.body.appendChild(d);
  var mw=d.offsetWidth,mh=d.offsetHeight,vw=window.innerWidth,vh=window.innerHeight;
  var links=Math.min(Math.max(8,r.left),Math.max(8,vw-mw-8));
  var oben=r.bottom+6;
  if(oben+mh>vh-8)oben=Math.max(8,r.top-mh-6);
  d.style.left=links+"px";d.style.top=oben+"px";
  var akt=d.querySelector(".stwahl.an");
  if(akt&&d.scrollHeight>d.clientHeight)akt.scrollIntoView({block:"center"});
  var w=d.querySelectorAll(".stwahl");
  for(var q=0;q<w.length;q++)w[q].onclick=function(ev){
    ev.stopPropagation();
    var v=this.getAttribute("data-v");
    stZu();
    if(v!==sel.value){
      sel.value=v;
      sel.dispatchEvent(new Event("change",{bubbles:true}));}};
  setTimeout(function(){
    document.addEventListener("mousedown",stAussen,true);
    document.addEventListener("keydown",stEsc,true);
    window.addEventListener("resize",stZu);
    window.addEventListener("scroll",stRollt,true);},0);}

(function(){
