    var s=e.target&&e.target.closest?e.target.closest("select.st"):null;
    if(!s||s.disabled)return;
    e.preventDefault();e.stopPropagation();
    stMenueAuf(s);},true);
  document.addEventListener("click",function(e){
    var s=e.target&&e.target.closest?e.target.closest("select.st"):null;
